import {projects,createArtwork} from './art.js';
import {createExhibition} from './exhibition.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const gsap=window.gsap;const preference=matchMedia('(prefers-reduced-motion:reduce)');
const state={target:0,current:0,activeId:0,entry:1,calm:preference.matches,modal:false,failed:false};let selected=[0,1,2,3,4,5],scene=null,travel=null,filterMotion=null,lastActive=-1,manualPause=false,entrance=null,opener=null;
await Promise.all([document.fonts.load('20px Space'),document.fonts.load('12px Mono')]);
const artwork=createArtwork().map((art,index)=>({...art,project:projects[index]}));
$('#year').textContent=new Date().getFullYear();
function projectAtTarget(){return Math.min(selected.length-1,Math.max(0,Math.round(state.target)));}
function progress(value){travel?.kill();travel=null;state.target=Math.max(0,Math.min(selected.length-1,value));if(state.calm||state.failed){state.current=state.target;state.activeId=selected[Math.round(state.target)];}scene?.invalidate();}
function select(slot){slot=Math.max(0,Math.min(selected.length-1,slot));travel?.kill();if(state.calm||state.failed||!gsap){progress(slot);return;}travel=gsap.to(state,{target:slot,duration:.95,ease:'power2.inOut',overwrite:'auto',onUpdate(){scene?.invalidate();},onComplete(){travel=null;}});}
function updateRail(){const rail=$('.index-rail');rail.innerHTML='';selected.forEach((id,slot)=>{const button=document.createElement('button');button.setAttribute('aria-label',`Show ${projects[id].title}`);button.setAttribute('aria-pressed','false');button.dataset.slot=slot;button.addEventListener('click',()=>select(slot));rail.append(button);});}
function paintSummary(){const id=state.failed?selected[projectAtTarget()]:state.activeId;if(id===lastActive)return;lastActive=id;const p=projects[id];$('#project-category').textContent=p.category;$('#project-name').textContent=p.title;$('#project-count').innerHTML=`${String(selected.indexOf(id)+1).padStart(2,'0')} <i>/</i> ${String(selected.length).padStart(2,'0')}`;$('#open-project').setAttribute('aria-label',`Explore ${p.title}`);$('.project-announcement').textContent=`${p.title}. ${p.category}. Concept ${selected.indexOf(id)+1} of ${selected.length}.`;$$('.index-rail button').forEach((button,index)=>{button.classList.toggle('active',index===selected.indexOf(id));button.setAttribute('aria-pressed',String(index===selected.indexOf(id)));});$('.fallback-poster').style.backgroundImage=`url('${artwork[id].preview}')`;$('.fallback-poster').style.backgroundSize='cover';$('.fallback-poster').querySelectorAll('span,strong').forEach(el=>el.hidden=true);if(gsap&&!state.calm)gsap.fromTo('.project-summary',{opacity:.1,y:5},{opacity:1,y:0,duration:.3,ease:'power2.out',overwrite:true});}
function filter(name){travel?.kill();filterMotion?.kill();const ids=projects.map((p,id)=>({p,id})).filter(({p})=>name==='all'||p.filter===name).map(({id})=>id);$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===name);b.setAttribute('aria-pressed',String(b.dataset.filter===name));});const apply=()=>{selected=ids;state.target=0;state.current=0;state.activeId=selected[0];scene?.setSelection(ids);scene?.invalidate();lastActive=-1;updateRail();paintSummary();};if(gsap&&!state.calm){filterMotion=gsap.timeline();filterMotion.to(state,{entry:0,duration:.18,ease:'power2.in',onUpdate(){scene?.invalidate();}}).call(apply).to(state,{entry:1,duration:.65,ease:'power3.out',onUpdate(){scene?.invalidate();}});}else{apply();state.entry=1;}}
updateRail();
try{scene=createExhibition($('#stage'),artwork,state,{onProject:openProject,onSelect:select,onProgress:progress});}catch(error){state.failed=true;console.warn('The standard gallery is available because the 3D scene could not start.',error);}
paintSummary();
const update=()=>paintSummary();if(gsap)gsap.ticker.add(update);else{const timer=setInterval(update,200);window.addEventListener('pagehide',()=>clearInterval(timer),{once:true});}
$$('[data-filter]').forEach(button=>button.addEventListener('click',()=>filter(button.dataset.filter)));
$('#next').addEventListener('click',()=>select((projectAtTarget()+1)%selected.length));$('#previous').addEventListener('click',()=>select((projectAtTarget()-1+selected.length)%selected.length));$('#open-project').addEventListener('click',()=>openProject(state.activeId));
$('#work-nav').addEventListener('click',()=>{filter('all');select(0);});$('.brand').addEventListener('click',e=>{e.preventDefault();filter('all');select(0);});
document.addEventListener('keydown',e=>{if(state.modal||e.target.matches('input,textarea,select'))return;if(['ArrowDown','ArrowRight','PageDown','ArrowUp','ArrowLeft','PageUp','Home','End'].includes(e.key)){e.preventDefault();if(e.key==='Home')select(0);else if(e.key==='End')select(selected.length-1);else select(projectAtTarget()+(['ArrowDown','ArrowRight','PageDown'].includes(e.key)?1:-1));}});
function motionPreference(){state.calm=preference.matches||manualPause;document.body.classList.toggle('calm',state.calm);if(state.calm){entrance?.progress(1);entrance?.kill();filterMotion?.progress(1);filterMotion?.kill();travel?.kill();state.entry=1;state.target=Math.round(state.target);state.current=state.target;}$('#motion').textContent=state.calm?'RESUME MOTION':'PAUSE MOTION';$('#motion').setAttribute('aria-pressed',String(state.calm));$('#motion').disabled=preference.matches;$('#motion').title=preference.matches?'Reduced motion follows your system preference':'';scene?.invalidate();}
$('#motion').addEventListener('click',()=>{manualPause=!manualPause;motionPreference();});preference.addEventListener('change',motionPreference);motionPreference();
if(gsap&&!state.calm){state.entry=0;entrance=gsap.timeline({defaults:{ease:'power3.out'}});entrance.to(state,{entry:1,duration:1.2,onUpdate(){scene?.invalidate();}},0).from('header,.exhibition-note',{opacity:0,y:-6,duration:.7},.25).from('.disciplines [data-filter]',{opacity:0,x:-8,duration:.6,stagger:.07},.6).from('.gallery-controls,footer,.scene-hint',{opacity:0,y:8,duration:.75},.8);}
function openDialog(dialog,source){opener=source||document.activeElement;state.modal=true;dialog.showModal();document.body.classList.add('modal-open');if(gsap&&!state.calm)gsap.fromTo(dialog,{opacity:0,y:17,scale:.985},{opacity:1,y:0,scale:1,duration:.38,ease:'power3.out',overwrite:true});}
function closeDialog(dialog){gsap?.killTweensOf(dialog);dialog.close();}
function openProject(id){const p=projects[id];$('#detail-title').textContent=p.title;$('#detail-category').textContent=p.category;$('#detail-description').textContent=p.description;$('#detail-tags').textContent=p.tags;$('.detail-art').style.backgroundImage=`url('${artwork[id].preview}')`;openDialog($('#project-dialog'),$('#open-project'));}
$$('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>closeDialog(d));d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d);}});d.addEventListener('close',()=>{const stillOpen=$$('dialog').some(other=>other.open);state.modal=stillOpen;document.body.classList.toggle('modal-open',stillOpen);if(!stillOpen)opener?.focus();scene?.invalidate();});});
$$('[data-studio]').forEach(b=>b.addEventListener('click',()=>openDialog($('#studio-dialog'),b)));$$('[data-contact]').forEach(b=>b.addEventListener('click',()=>openDialog($('#contact-dialog'),b)));
for(const [button,dialog] of [['#project-contact','#project-dialog'],['#studio-contact','#studio-dialog']])$(button).addEventListener('click',()=>{closeDialog($(dialog));openDialog($('#contact-dialog'),$('#open-project'));});
$$('.services details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open){$$('.services details').forEach(other=>{if(other!==d)other.open=false;});if(gsap&&!state.calm)gsap.fromTo(d.querySelector('p'),{opacity:0,y:-5},{opacity:1,y:0,duration:.3,overwrite:true});}}));
let inquiryText='';$('#inquiry').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const d=new FormData(form);inquiryText=`Hi Red Studio,\n\nI'm ${d.get('name')}. I'd love to explore an idea with you.\n\n${d.get('idea')}\n\nI'm looking for: ${d.get('discipline')}.\n\nYou can reach me at ${d.get('email')}.\n\n${d.get('name')}`;$('#email-draft').href=`mailto:theredstudio@gmail.com?subject=${encodeURIComponent('A new idea — '+d.get('name'))}&body=${encodeURIComponent(inquiryText)}`;$('#draft-actions').hidden=false;form.querySelector('[type=submit]').hidden=true;$('#form-status').textContent='Your draft is ready. Open your email app to review and send it.';});
$('#inquiry').addEventListener('input',()=>{if(!$('#draft-actions').hidden){$('#draft-actions').hidden=true;$('#inquiry [type=submit]').hidden=false;$('#form-status').textContent='Your idea changed. Prepare a fresh draft when you’re ready.';}});
$('#copy-inquiry').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(inquiryText);$('#form-status').textContent='Copied. Paste your inquiry into an email to theredstudio@gmail.com.';}catch{let field=$('#copy-fallback');if(!field){field=document.createElement('textarea');field.id='copy-fallback';field.setAttribute('aria-label','Inquiry text to copy');$('#draft-actions').append(field);}field.value=inquiryText;field.focus();field.select();$('#form-status').textContent='Select and copy the inquiry below.';}});
let audio=null,soundOn=false;
function buildAudio(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw new Error('Audio unavailable');const context=new AC(),master=context.createGain();master.gain.value=0;master.connect(context.destination);const lowpass=context.createBiquadFilter();lowpass.type='lowpass';lowpass.frequency.value=490;lowpass.connect(master);const voices=[61.74,92.5,123.47,185].map((hz,index)=>{const oscillator=context.createOscillator(),gain=context.createGain();oscillator.type=index===0?'sine':'triangle';oscillator.frequency.value=hz;gain.gain.value=index===0?.2:.025;oscillator.connect(gain);gain.connect(lowpass);oscillator.start();return oscillator;});return {context,master,voices};}
$('#audio').addEventListener('click',async()=>{try{audio??=buildAudio();await audio.context.resume();soundOn=!soundOn;audio.master.gain.setTargetAtTime(soundOn?.24:0,audio.context.currentTime,.3);$('#audio-label').textContent=soundOn?'SOUND ON':'SOUND OFF';$('#audio').setAttribute('aria-label',soundOn?'Disable ambient sound':'Enable ambient sound');$('#audio').setAttribute('aria-pressed',String(soundOn));document.body.classList.toggle('audio-on',soundOn);}catch{$('#audio-label').textContent='UNAVAILABLE';$('#audio').disabled=true;}});
document.addEventListener('visibilitychange',()=>{if(audio)audio.master.gain.setTargetAtTime(soundOn&&!document.hidden?.24:0,audio.context.currentTime,.12);});
window.addEventListener('pagehide',event=>{if(event.persisted)return;travel?.kill();filterMotion?.kill();entrance?.kill();gsap?.ticker.remove(update);scene?.dispose();audio?.context.close();preference.removeEventListener('change',motionPreference);});
